-- WoundAI v30.5 security hardening and database-generated audit trail.
-- Apply only after the v30.1 core and v30.2 backend migrations.
-- Review in a dedicated Supabase staging project before production.

begin;

-- Audit entries are generated by database triggers. Clients may read them
-- under the existing owner/admin RLS policy but may not forge or rewrite them.
drop policy if exists "members append audit" on public.audit_events;
alter table public.audit_events alter column actor_id drop not null;
revoke insert, update, delete on public.audit_events from anon, authenticated;
grant select on public.audit_events to authenticated;

create or replace function public.woundai_write_audit_event()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  old_row jsonb;
  new_row jsonb;
  row_data jsonb;
  target_clinic uuid;
  target_resource uuid;
  changed_fields jsonb := '[]'::jsonb;
  actor uuid;
  action_name text := lower(tg_op);
begin
  if tg_op in ('UPDATE','DELETE') then old_row := to_jsonb(old); end if;
  if tg_op in ('INSERT','UPDATE') then new_row := to_jsonb(new); end if;
  row_data := coalesce(new_row, old_row);

  if tg_table_name = 'clinics' then
    target_clinic := (row_data->>'id')::uuid;
  else
    target_clinic := (row_data->>'clinic_id')::uuid;
  end if;

  target_resource := coalesce(
    nullif(row_data->>'id','')::uuid,
    nullif(row_data->>'user_id','')::uuid
  );
  actor := auth.uid();

  -- Cascaded child deletes during clinic removal cannot be referenced by
  -- audit_events because the parent clinic is already being deleted.
  if target_clinic is null then
    if tg_op = 'DELETE' then return old; else return new; end if;
  end if;
  if tg_op = 'DELETE' and not exists (
    select 1 from public.clinics where id = target_clinic
  ) then
    return old;
  end if;

  if tg_op = 'UPDATE' then
    select coalesce(jsonb_agg(k order by k), '[]'::jsonb)
      into changed_fields
      from jsonb_object_keys(new_row) as keys(k)
     where old_row->k is distinct from new_row->k;
  elsif tg_op = 'INSERT' then
    select coalesce(jsonb_agg(k order by k), '[]'::jsonb)
      into changed_fields
      from jsonb_object_keys(new_row) as keys(k)
     where k not in ('created_at','updated_at');
  else
    select coalesce(jsonb_agg(k order by k), '[]'::jsonb)
      into changed_fields
      from jsonb_object_keys(old_row) as keys(k)
     where k not in ('created_at','updated_at');
  end if;

  insert into public.audit_events (
    clinic_id, actor_id, action, resource_type, resource_id, metadata
  ) values (
    target_clinic,
    actor,
    action_name,
    tg_table_name,
    target_resource,
    jsonb_build_object(
      'source', 'database_trigger',
      'changed_fields', changed_fields,
      'transaction_id', txid_current()
    )
  );

  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$$;

revoke all on function public.woundai_write_audit_event() from public, anon, authenticated;

drop trigger if exists woundai_audit_clinics on public.clinics;
create trigger woundai_audit_clinics
after insert or update on public.clinics
for each row execute function public.woundai_write_audit_event();

drop trigger if exists woundai_audit_clinic_members on public.clinic_members;
create trigger woundai_audit_clinic_members
after insert or update or delete on public.clinic_members
for each row execute function public.woundai_write_audit_event();

drop trigger if exists woundai_audit_patients on public.patients;
create trigger woundai_audit_patients
after insert or update or delete on public.patients
for each row execute function public.woundai_write_audit_event();

drop trigger if exists woundai_audit_wounds on public.wounds;
create trigger woundai_audit_wounds
after insert or update or delete on public.wounds
for each row execute function public.woundai_write_audit_event();

drop trigger if exists woundai_audit_wound_images on public.wound_images;
create trigger woundai_audit_wound_images
after insert or update or delete on public.wound_images
for each row execute function public.woundai_write_audit_event();

drop trigger if exists woundai_audit_assessments on public.assessments;
create trigger woundai_audit_assessments
after insert or update or delete on public.assessments
for each row execute function public.woundai_write_audit_event();

drop trigger if exists woundai_audit_care_plans on public.care_plans;
create trigger woundai_audit_care_plans
after insert or update or delete on public.care_plans
for each row execute function public.woundai_write_audit_event();

create index if not exists audit_events_clinic_time_idx
  on public.audit_events(clinic_id, occurred_at desc);
create index if not exists audit_events_resource_idx
  on public.audit_events(resource_type, resource_id, occurred_at desc);

commit;
